/* Original HTSE practice question bank. Browser-side scoring is for practice only. */
window.HTSE_QUESTION_BANK = Object.freeze({"paramedical":{"label":"Paramedical","description":"Common foundational knowledge across allied and healthcare pathways.","questions":[{"id":"PARA-001","question":"Which anatomical position is used as the standard reference when describing body structures?","options":["Standing with the back facing forward","Lying face down with palms inward","Standing upright, facing forward, arms at the sides, palms forward","Sitting with arms crossed"],"answer":2,"explanation":"The anatomical position is upright, face forward, arms by the sides and palms facing anteriorly.","topic":"Anatomy basics","difficulty":"Easy"},{"id":"PARA-002","question":"The term 'anterior' means:","options":["Away from the midline","Toward the feet","Toward the front of the body","Toward the back"],"answer":2,"explanation":"Anterior describes the front surface; posterior describes the back.","topic":"Anatomy basics","difficulty":"Easy"},{"id":"PARA-003","question":"A structure closer to the midline is described as:","options":["Superficial","Distal","Medial","Lateral"],"answer":2,"explanation":"Medial means nearer the body's midline.","topic":"Anatomy basics","difficulty":"Moderate"},{"id":"PARA-004","question":"Which plane divides the body into right and left portions?","options":["Transverse plane","Oblique plane","Sagittal plane","Coronal plane"],"answer":2,"explanation":"A sagittal plane divides the body into right and left parts; a midsagittal plane makes equal halves.","topic":"Anatomy basics","difficulty":"Easy"},{"id":"PARA-005","question":"Which tissue primarily covers body surfaces and lines many cavities?","options":["Epithelial tissue","Nervous tissue","Cartilage","Skeletal muscle"],"answer":0,"explanation":"Epithelium covers surfaces, lines cavities and forms glands.","topic":"Tissues","difficulty":"Easy"},{"id":"PARA-006","question":"The basic structural and functional unit of the human body is the:","options":["Organ","Cell","System","Tissue"],"answer":1,"explanation":"Cells are the smallest living structural and functional units of the body.","topic":"Cell biology","difficulty":"Moderate"},{"id":"PARA-007","question":"Which organelle is most directly associated with ATP production?","options":["Golgi apparatus","Ribosome","Mitochondrion","Lysosome"],"answer":2,"explanation":"Mitochondria generate much of the cell's ATP through aerobic metabolism.","topic":"Cell biology","difficulty":"Easy"},{"id":"PARA-008","question":"Which blood component is mainly responsible for oxygen transport?","options":["Platelets","White blood cells","Red blood cells","Plasma proteins"],"answer":2,"explanation":"Haemoglobin inside red blood cells binds and transports most oxygen.","topic":"Blood","difficulty":"Easy"},{"id":"PARA-009","question":"Which blood component plays a major role in clot formation?","options":["Lymphocytes","Albumin","Erythrocytes","Platelets"],"answer":3,"explanation":"Platelets adhere and aggregate at sites of vessel injury and support coagulation.","topic":"Blood","difficulty":"Moderate"},{"id":"PARA-010","question":"Which blood cells are central to immune defence?","options":["White blood cells","Reticulocytes","Platelets","Red blood cells"],"answer":0,"explanation":"Leukocytes include cells involved in innate and adaptive immune responses.","topic":"Blood","difficulty":"Easy"},{"id":"PARA-011","question":"The main function of haemoglobin is to:","options":["Produce antibodies","Filter urine","Bind and transport oxygen","Digest fats"],"answer":2,"explanation":"Haemoglobin in red blood cells reversibly binds oxygen in the lungs and releases it to tissues.","topic":"Blood","difficulty":"Easy"},{"id":"PARA-012","question":"Which organ pumps blood through the systemic and pulmonary circulations?","options":["Heart","Liver","Kidney","Spleen"],"answer":0,"explanation":"The heart is the muscular pump that maintains circulation.","topic":"Cardiovascular","difficulty":"Moderate"},{"id":"PARA-013","question":"Which blood vessels usually carry blood away from the heart?","options":["Arteries","Capillaries","Lymphatics","Veins"],"answer":0,"explanation":"Arteries carry blood away from the heart; pulmonary arteries are an exception to the usual oxygenation pattern.","topic":"Cardiovascular","difficulty":"Easy"},{"id":"PARA-014","question":"The exchange of gases between air and blood occurs mainly in the:","options":["Trachea","Alveoli","Pleural cavity","Larynx"],"answer":1,"explanation":"Alveoli provide a thin, large surface area for oxygen and carbon dioxide exchange.","topic":"Respiratory","difficulty":"Easy"},{"id":"PARA-015","question":"Which muscle is the primary driver of quiet inspiration?","options":["Biceps brachii","Deltoid","Masseter","Diaphragm"],"answer":3,"explanation":"Contraction of the diaphragm increases thoracic volume and helps draw air into the lungs.","topic":"Respiratory","difficulty":"Moderate"},{"id":"PARA-016","question":"The functional unit of the kidney is the:","options":["Osteon","Alveolus","Neuron","Nephron"],"answer":3,"explanation":"Each nephron filters blood and modifies filtrate to form urine.","topic":"Renal","difficulty":"Easy"},{"id":"PARA-017","question":"Which organ produces insulin?","options":["Adrenal cortex","Pancreas","Thyroid gland","Pituitary gland"],"answer":1,"explanation":"Insulin is produced by beta cells in the pancreatic islets.","topic":"Endocrine","difficulty":"Easy"},{"id":"PARA-018","question":"Which hormone helps the kidneys conserve water?","options":["Thyroxine","Adrenaline","Antidiuretic hormone (ADH)","Insulin"],"answer":2,"explanation":"ADH increases water reabsorption in the renal collecting ducts.","topic":"Endocrine","difficulty":"Moderate"},{"id":"PARA-019","question":"Which structure protects the brain?","options":["Patella","Pelvis","Skull (cranium)","Sternum"],"answer":2,"explanation":"The cranium forms a bony protective case around the brain.","topic":"Musculoskeletal","difficulty":"Easy"},{"id":"PARA-020","question":"A joint that permits movement in many directions, such as the shoulder, is a:","options":["Pivot joint","Ball-and-socket joint","Fibrous suture","Hinge joint"],"answer":1,"explanation":"The shoulder is a ball-and-socket synovial joint with a wide range of movement.","topic":"Musculoskeletal","difficulty":"Easy"},{"id":"PARA-021","question":"Which instrument is commonly used to measure body temperature?","options":["Sphygmomanometer","Pulse oximeter","Stethoscope","Clinical thermometer"],"answer":3,"explanation":"A thermometer measures temperature; the device type depends on the clinical setting.","topic":"Vital signs","difficulty":"Moderate"},{"id":"PARA-022","question":"A sphygmomanometer is used to measure:","options":["Blood pressure","Respiratory rate","Body temperature","Blood glucose"],"answer":0,"explanation":"A sphygmomanometer measures arterial blood pressure, usually with a cuff.","topic":"Vital signs","difficulty":"Easy"},{"id":"PARA-023","question":"A pulse oximeter estimates:","options":["Blood pressure continuously","Peripheral oxygen saturation and pulse rate","Haemoglobin concentration directly","Blood glucose and ketones"],"answer":1,"explanation":"A pulse oximeter estimates oxygen saturation (SpO2) and pulse rate using light absorption.","topic":"Vital signs","difficulty":"Easy"},{"id":"PARA-024","question":"Which unit is commonly used to report blood pressure?","options":["mEq/L","mmHg","cmH2O only","mg/dL"],"answer":1,"explanation":"Blood pressure is commonly expressed in millimetres of mercury (mmHg).","topic":"Vital signs","difficulty":"Moderate"},{"id":"PARA-025","question":"A typical resting adult pulse rate is commonly in which range?","options":["140-180 beats per minute","About 60-100 beats per minute","10-20 beats per minute","25-40 beats per minute"],"answer":1,"explanation":"A common reference range for resting adults is about 60-100 beats/min; clinical context matters.","topic":"Vital signs","difficulty":"Easy"},{"id":"PARA-026","question":"Which anticoagulant is commonly used in lavender-top tubes for a complete blood count?","options":["Sodium citrate","Plain clot activator","Sodium fluoride","EDTA"],"answer":3,"explanation":"EDTA chelates calcium and is widely used for haematology specimens such as CBC.","topic":"Laboratory practice","difficulty":"Easy"},{"id":"PARA-027","question":"Which anticoagulant is commonly used in light-blue-top tubes for coagulation tests?","options":["Sodium citrate","Sodium fluoride","Heparin only","EDTA"],"answer":0,"explanation":"Citrate binds calcium reversibly and is used for many coagulation assays.","topic":"Laboratory practice","difficulty":"Moderate"},{"id":"PARA-028","question":"A grey-top tube commonly contains which additive for glucose testing?","options":["Sodium fluoride with an anticoagulant","No additive","Sodium citrate only","EDTA only"],"answer":0,"explanation":"Fluoride helps inhibit glycolysis in the specimen; exact tube formulations vary by laboratory.","topic":"Laboratory practice","difficulty":"Easy"},{"id":"PARA-029","question":"Before collecting a blood specimen, the patient should be identified using:","options":["Room number only","Visual recognition by the collector","At least two approved identifiers","Bed number only"],"answer":2,"explanation":"Using two identifiers reduces wrong-patient specimen errors; bed or room number alone is not sufficient.","topic":"Patient safety","difficulty":"Easy"},{"id":"PARA-030","question":"A specimen label should ideally be applied:","options":["Only after the sample reaches the lab","Before the patient is identified","At the end of the shift","Immediately after collection, in the presence of the patient"],"answer":3,"explanation":"Immediate bedside labelling reduces specimen misidentification.","topic":"Laboratory practice","difficulty":"Moderate"},{"id":"PARA-031","question":"The main purpose of quality control material in a laboratory is to:","options":["Increase sample volume","Sterilise laboratory benches","Replace patient samples","Monitor whether an analytical process is performing acceptably"],"answer":3,"explanation":"Quality control helps detect analytical problems before results are released.","topic":"Quality assurance","difficulty":"Easy"},{"id":"PARA-032","question":"A sample with visible haemolysis may interfere with some tests because:","options":["The sample has no measurable proteins","The tube becomes sterile","Cell contents are released into the serum or plasma","All analytes are destroyed equally"],"answer":2,"explanation":"Haemolysis releases intracellular contents such as potassium and haemoglobin, affecting some measurements.","topic":"Laboratory practice","difficulty":"Easy"},{"id":"PARA-033","question":"Which microscope component is used to adjust the amount of light passing through a specimen?","options":["Stage clip","Diaphragm","Coarse focus knob","Arm"],"answer":1,"explanation":"The iris diaphragm regulates light reaching the specimen.","topic":"Microscopy","difficulty":"Moderate"},{"id":"PARA-034","question":"The 100x oil-immersion objective is most commonly used for:","options":["Measuring blood pressure","High-resolution viewing of bacteria and other very small structures","Counting urine volume","Scanning the whole slide at low power"],"answer":1,"explanation":"Oil immersion improves resolution at high magnification by reducing light refraction.","topic":"Microscopy","difficulty":"Easy"},{"id":"PARA-035","question":"In the Gram stain, the primary stain is:","options":["Acid alcohol","Crystal violet","Methylene blue","Safranin"],"answer":1,"explanation":"Crystal violet is the initial primary stain; iodine is the mordant, followed by decolorisation and counterstaining.","topic":"Microbiology","difficulty":"Easy"},{"id":"PARA-036","question":"Which microorganism group includes organisms that lack a true nucleus?","options":["Helminths","Protozoa","Fungi","Bacteria"],"answer":3,"explanation":"Bacteria are prokaryotes and do not have a membrane-bound nucleus.","topic":"Microbiology","difficulty":"Moderate"},{"id":"PARA-037","question":"A culture and sensitivity test is used to help:","options":["Measure blood pressure","Identify a microorganism and assess antimicrobial susceptibility","Estimate body temperature","Determine blood group only"],"answer":1,"explanation":"Culture can identify organisms; susceptibility testing guides appropriate antimicrobial choices.","topic":"Microbiology","difficulty":"Easy"},{"id":"PARA-038","question":"Which specimen is generally preferred for a routine urine culture?","options":["First drops from an unclean container","Urine collected from the floor","Urine mixed with tap water","Clean-catch midstream urine"],"answer":3,"explanation":"A clean-catch midstream sample helps reduce contamination from skin and distal urethral flora.","topic":"Specimen collection","difficulty":"Easy"},{"id":"PARA-039","question":"The best way to reduce contamination during specimen collection is to:","options":["Reuse collection containers","Leave the sample uncovered","Touch the inside of the container","Follow the prescribed aseptic or clean-catch collection method"],"answer":3,"explanation":"Following collection instructions and avoiding contact with sterile surfaces helps reduce contamination.","topic":"Specimen collection","difficulty":"Moderate"},{"id":"PARA-040","question":"Which measure is part of the ALARA principle in diagnostic imaging?","options":["Use radiation exposure As Low As Reasonably Achievable","Repeat every image several times","Avoid checking patient identity","Use the highest exposure setting"],"answer":0,"explanation":"ALARA means optimising exposure while obtaining the diagnostic information required.","topic":"Radiation safety","difficulty":"Easy"},{"id":"PARA-041","question":"A lead apron is used in radiology primarily to:","options":["Measure radiation dose","Reduce unnecessary exposure to parts of the body","Increase image magnification","Sterilise the patient"],"answer":1,"explanation":"Appropriate shielding may reduce exposure to selected body areas when indicated by current protocols.","topic":"Radiation safety","difficulty":"Easy"},{"id":"PARA-042","question":"Before a contrast-enhanced imaging procedure, staff should verify relevant history such as:","options":["Shoe size","Preferred music","Favourite food","Previous contrast reaction and relevant clinical risk factors"],"answer":3,"explanation":"Checking prior reactions, kidney function and other relevant risks follows local contrast safety protocols.","topic":"Radiology safety","difficulty":"Moderate"},{"id":"PARA-043","question":"The purpose of a radiographic marker is to:","options":["Measure patient pulse","Increase radiation dose","Identify the side or orientation of the image","Sterilise the detector"],"answer":2,"explanation":"Correct markers help prevent laterality and orientation errors in imaging.","topic":"Radiology","difficulty":"Easy"},{"id":"PARA-044","question":"Which device is commonly used to record the electrical activity of the heart?","options":["Glucometer","Electrocardiograph (ECG)","Spirometer","Otoscope"],"answer":1,"explanation":"An ECG records electrical signals associated with cardiac activity.","topic":"Cardiac diagnostics","difficulty":"Easy"},{"id":"PARA-045","question":"An ECG electrode should be applied to:","options":["A metal bed rail","A wound dressing without assessment","Clean, dry skin according to the lead-placement protocol","Wet clothing"],"answer":2,"explanation":"Good skin contact improves signal quality; preparation follows the ECG protocol.","topic":"Cardiac diagnostics","difficulty":"Moderate"},{"id":"PARA-046","question":"The main purpose of sterilisation is to:","options":["Reduce odour","Destroy or remove all forms of microbial life, including spores","Remove visible dust only","Clean only the outside of equipment"],"answer":1,"explanation":"Sterilisation is a validated process intended to eliminate all forms of viable microorganisms.","topic":"Sterilisation","difficulty":"Easy"},{"id":"PARA-047","question":"Disinfection differs from sterilisation because disinfection:","options":["Always destroys every spore","Is only used on living tissue","Does not reduce microorganisms","May not eliminate all bacterial spores"],"answer":3,"explanation":"Disinfection reduces or inactivates many pathogens but may not destroy bacterial spores.","topic":"Sterilisation","difficulty":"Easy"},{"id":"PARA-048","question":"A commonly used moist-heat sterilisation device is an:","options":["Refrigerator","Centrifuge","Incubator","Autoclave"],"answer":3,"explanation":"An autoclave uses pressurised steam under validated time-temperature conditions.","topic":"Sterilisation","difficulty":"Moderate"},{"id":"PARA-049","question":"The purpose of a biological indicator in sterilisation monitoring is to:","options":["Replace all chemical indicators","Measure room temperature","Provide evidence that a sterilisation process can inactivate resistant spores","Check staff attendance"],"answer":2,"explanation":"Biological indicators use resistant spores to assess sterilisation process effectiveness.","topic":"Sterilisation","difficulty":"Easy"},{"id":"PARA-050","question":"Which item should be discarded into a puncture-resistant sharps container?","options":["Clean paper wrapper","Used hypodermic needle","Food waste","Uncontaminated cardboard"],"answer":1,"explanation":"Needles and other sharps must go into designated puncture-resistant containers.","topic":"Biomedical waste","difficulty":"Easy"},{"id":"PARA-051","question":"Sharps containers should be closed and replaced:","options":["Only when they overflow","Before they exceed the marked fill line","After being emptied by hand","Once a year regardless of fill"],"answer":1,"explanation":"Containers should not be overfilled; follow local biomedical waste policy and fill markings.","topic":"Biomedical waste","difficulty":"Moderate"},{"id":"PARA-052","question":"The most effective routine action to reduce healthcare-associated infection transmission is:","options":["Wear the same gloves between patients","Keep windows closed","Use perfume","Perform hand hygiene at the recommended moments"],"answer":3,"explanation":"Hand hygiene is a central infection prevention measure; WHO describes five key moments.","topic":"Infection prevention","difficulty":"Easy"},{"id":"PARA-053","question":"Which is an example of personal protective equipment (PPE)?","options":["Stethoscope only","Gloves","Patient chart","Bedside table"],"answer":1,"explanation":"Gloves, gowns, masks and eye protection are examples of PPE selected by risk assessment.","topic":"Infection prevention","difficulty":"Easy"},{"id":"PARA-054","question":"Standard precautions should be applied:","options":["Only during outbreaks","Only to patients with a known infection","To every patient, based on the anticipated exposure risk","Only in the operating theatre"],"answer":2,"explanation":"Standard precautions apply to all patient care, regardless of suspected or confirmed infection status.","topic":"Infection prevention","difficulty":"Moderate"},{"id":"PARA-055","question":"A sterile field is considered contaminated if:","options":["It contains sterile instruments","It is prepared on a clean surface","A non-sterile object touches it","It is within the clinician's view"],"answer":2,"explanation":"Contact with a non-sterile object compromises sterility.","topic":"Aseptic technique","difficulty":"Easy"},{"id":"PARA-056","question":"The correct response to a needlestick injury is to:","options":["Squeeze aggressively and continue work","Ignore it if there is no bleeding","Apply household glue","Wash the area promptly and report immediately according to protocol"],"answer":3,"explanation":"Prompt first aid, reporting and risk assessment are essential after occupational exposure.","topic":"Occupational safety","difficulty":"Easy"},{"id":"PARA-057","question":"Biomedical waste should be segregated:","options":["Only at the central storage site","At the end of the week","At the point where it is generated","After mixing all waste together"],"answer":2,"explanation":"Point-of-generation segregation reduces handling and disposal risks.","topic":"Biomedical waste","difficulty":"Moderate"},{"id":"PARA-058","question":"A safety data sheet provides information about:","options":["Equipment purchase price only","Patient diagnosis","Hazards, safe handling and emergency measures for a chemical","Hospital staff leave balance"],"answer":2,"explanation":"Safety data sheets describe chemical hazards, handling, storage and emergency response.","topic":"Laboratory safety","difficulty":"Easy"},{"id":"PARA-059","question":"A centrifuge should be operated only after:","options":["Holding the rotor by hand","Removing the lid while spinning","Placing all tubes on one side","Balancing opposing tubes according to the manufacturer's instructions"],"answer":3,"explanation":"Balanced loading reduces vibration, equipment damage and potential injury.","topic":"Laboratory safety","difficulty":"Easy"},{"id":"PARA-060","question":"A laboratory reagent should be labelled with:","options":["No label if stored in a fridge","Only the colour of the bottle","Identity, concentration where relevant, preparation or expiry details and hazard information","The name of the person who last used it"],"answer":2,"explanation":"Clear reagent labelling supports traceability and safe use.","topic":"Laboratory safety","difficulty":"Moderate"},{"id":"PARA-061","question":"A first-aid response to external bleeding generally begins with:","options":["Giving food immediately","Removing embedded objects forcefully","Applying soil to the wound","Applying firm direct pressure with an appropriate dressing"],"answer":3,"explanation":"Direct pressure is a standard first response to external bleeding while emergency help is arranged as appropriate.","topic":"Basic emergency care","difficulty":"Easy"},{"id":"PARA-062","question":"In the primary assessment of an unwell person, ABC commonly stands for:","options":["Air, Bones, Chest","Anatomy, Blood, Cells","Airway, Breathing, Circulation","Alertness, Balance, Colour"],"answer":2,"explanation":"ABC is a widely used initial assessment framework; follow the relevant training and protocol.","topic":"Basic emergency care","difficulty":"Easy"},{"id":"PARA-063","question":"The recovery position is generally used for a person who is:","options":["Having a suspected spinal injury without assessment","Alert and walking","Unresponsive but breathing normally, when no contraindication is present","Not breathing normally"],"answer":2,"explanation":"The recovery position can help maintain an open airway in an unresponsive person who is breathing normally; follow BLS guidance.","topic":"Basic emergency care","difficulty":"Moderate"},{"id":"PARA-064","question":"The purpose of a hospital incident report is to:","options":["Guarantee that an event never recurs","Replace the clinical record","Assign blame automatically","Document an incident and support learning and risk reduction"],"answer":3,"explanation":"Incident reporting supports review and improvement; it should follow organisational policy.","topic":"Quality and safety","difficulty":"Easy"},{"id":"PARA-065","question":"A near miss is an event that:","options":["Is the same as a planned procedure","Could have caused harm but did not reach the patient or cause harm","Always causes permanent injury","Must never be reported"],"answer":1,"explanation":"Near-miss reporting helps identify system risks before harm occurs.","topic":"Quality and safety","difficulty":"Easy"},{"id":"PARA-066","question":"The safest way to confirm a patient's identity before a procedure is to:","options":["Ask the bed number","Assume the name from the door","Ask the patient to state approved identifiers and check against the record","Ask another patient"],"answer":2,"explanation":"Use approved identifiers and match them to the record and procedure documentation.","topic":"Patient safety","difficulty":"Moderate"},{"id":"PARA-067","question":"Informed consent should be obtained:","options":["Before the procedure, after the patient receives understandable information and has a chance to decide","Only from a visitor in every case","Without explaining the procedure","After the procedure"],"answer":0,"explanation":"Consent requires information, understanding, capacity and a voluntary decision, consistent with policy and law.","topic":"Ethics","difficulty":"Easy"},{"id":"PARA-068","question":"Confidential patient information should be shared:","options":["In a public social-media post","With anyone who asks","Only with authorised people for a legitimate care or legal purpose","With friends out of curiosity"],"answer":2,"explanation":"Confidentiality is a core professional duty; disclosure requires appropriate authority and purpose.","topic":"Ethics","difficulty":"Easy"},{"id":"PARA-069","question":"A patient record entry should be:","options":["Altered without trace","Filled with personal opinions","Accurate, timely, factual and attributable to the person making it","Written later from memory when convenient"],"answer":2,"explanation":"Documentation should be clear, factual, contemporaneous and traceable.","topic":"Documentation","difficulty":"Moderate"},{"id":"PARA-070","question":"If a test result appears inconsistent with the specimen or clinical information, the first safe step is to:","options":["Delete the result","Follow the laboratory's verification and escalation process before release","Release it without checks","Change the value to look normal"],"answer":1,"explanation":"Unexpected results require verification and appropriate escalation under laboratory policy.","topic":"Quality assurance","difficulty":"Easy"},{"id":"PARA-071","question":"The purpose of a reference range is to:","options":["Provide a comparison interval for results in a defined population and method","Guarantee a diagnosis","Remain identical for every laboratory and age","Replace clinical assessment"],"answer":0,"explanation":"Reference intervals depend on population, method and context and do not diagnose alone.","topic":"Laboratory interpretation","difficulty":"Easy"},{"id":"PARA-072","question":"A control sample outside its acceptable limits usually means:","options":["The analytical run should be investigated before patient results are released","The instrument should be used faster","All patient results are automatically normal","The control can be ignored"],"answer":0,"explanation":"Out-of-control QC requires investigation and corrective action according to the laboratory SOP.","topic":"Quality assurance","difficulty":"Moderate"},{"id":"PARA-073","question":"Which is the best way to communicate with a patient who is anxious?","options":["Use unexplained technical terms","Listen attentively, use clear language and acknowledge their concerns","Interrupt frequently","Dismiss the concern"],"answer":1,"explanation":"Respectful, understandable communication builds trust and supports patient-centred care.","topic":"Communication","difficulty":"Easy"},{"id":"PARA-074","question":"When handing over a patient, the most useful approach is to:","options":["Omit important changes","Use informal rumours","Communicate relevant facts in a structured, standardised format","Rely on memory alone"],"answer":2,"explanation":"Structured handover reduces information gaps; use the local approved format.","topic":"Communication","difficulty":"Easy"},{"id":"PARA-075","question":"Which action best supports safe teamwork?","options":["Assume everyone knows the plan","Clarify roles and communicate changes promptly","Avoid asking questions","Hide equipment problems"],"answer":1,"explanation":"Clear role allocation and timely communication support coordinated care.","topic":"Teamwork","difficulty":"Moderate"},{"id":"PARA-076","question":"A patient's cultural or religious preferences should be:","options":["Asked about respectfully and accommodated where safe and feasible","Ignored","Discussed publicly without permission","Assumed from appearance"],"answer":0,"explanation":"Culturally responsive care avoids assumptions and respects patient preferences.","topic":"Patient-centred care","difficulty":"Easy"},{"id":"PARA-077","question":"A professional should report an equipment fault because:","options":["It may create a risk to patients and staff","It improves the equipment's appearance","It is not relevant to safety","Only managers can identify faults"],"answer":0,"explanation":"Faulty equipment should be labelled, removed from use where required and reported.","topic":"Equipment safety","difficulty":"Easy"},{"id":"PARA-078","question":"The purpose of a standard operating procedure (SOP) is to:","options":["Serve only as a marketing document","Describe an approved, consistent method for carrying out a task","Replace all training","Allow each person to improvise"],"answer":1,"explanation":"SOPs standardise steps and responsibilities and should be current and accessible.","topic":"Quality systems","difficulty":"Moderate"},{"id":"PARA-079","question":"A clean utility area is primarily intended for:","options":["Food waste disposal","Storage and preparation of clean supplies","Storage of infectious waste","Dirty instrument decontamination"],"answer":1,"explanation":"Clean and dirty workflows should be separated to limit cross-contamination.","topic":"Healthcare environment","difficulty":"Easy"},{"id":"PARA-080","question":"The principle of ergonomics in patient handling aims to:","options":["Reduce injury risk by using safe posture, aids and team assistance","Increase manual lifting load","Avoid mechanical aids","Twist the spine while lifting"],"answer":0,"explanation":"Ergonomic technique and appropriate aids protect both patients and staff.","topic":"Occupational safety","difficulty":"Easy"},{"id":"PARA-081","question":"When moving a patient with limited mobility, staff should first:","options":["Assess the patient's ability and plan the move with suitable assistance","Ignore lines and tubes","Move without explaining","Pull the patient by the arms"],"answer":0,"explanation":"A safe transfer begins with assessment, explanation, equipment and adequate help.","topic":"Patient handling","difficulty":"Moderate"},{"id":"PARA-082","question":"The main reason to check expiry dates on clinical supplies is to:","options":["Avoid stock counts","Improve colour matching","Ensure products are within their validated use period","Reduce documentation"],"answer":2,"explanation":"Expired items may not retain the required performance or sterility assurance.","topic":"Equipment safety","difficulty":"Easy"},{"id":"PARA-083","question":"Which term describes the time from receipt of a specimen to reporting a result?","options":["Turnaround time","Incubation only","Half-life","Sensitivity"],"answer":0,"explanation":"Turnaround time tracks the interval from a defined starting point to result reporting.","topic":"Laboratory operations","difficulty":"Easy"},{"id":"PARA-084","question":"Which is the correct action if a specimen container leaks during transport?","options":["Use the spill and exposure procedure and notify the responsible team","Ignore the leak","Open it with bare hands","Wipe it on clothing"],"answer":0,"explanation":"Leaking specimens are a biohazard and require PPE, containment and reporting according to SOP.","topic":"Specimen safety","difficulty":"Moderate"},{"id":"PARA-085","question":"Which item should be checked before using a patient-monitoring device?","options":["Only its colour","Power, sensor condition, alarm settings and device readiness","The patient's favourite brand","Whether the cable is decorative"],"answer":1,"explanation":"Device readiness checks help ensure reliable monitoring and timely alarms.","topic":"Equipment safety","difficulty":"Easy"},{"id":"PARA-086","question":"A false-positive test result means:","options":["The test is positive even though the target condition is absent","The test is always correct","The test is negative when the condition is present","The sample was never tested"],"answer":0,"explanation":"A false positive is a positive result in someone without the target condition.","topic":"Diagnostics","difficulty":"Easy"},{"id":"PARA-087","question":"Sensitivity of a diagnostic test is its ability to:","options":["Identify people who do not have the condition","Identify people who truly have the condition","Measure cost","Predict the exact treatment response"],"answer":1,"explanation":"Sensitivity is the proportion of people with the condition who test positive.","topic":"Diagnostics","difficulty":"Moderate"},{"id":"PARA-088","question":"Which action best protects electronic patient information?","options":["Share passwords with colleagues","Send records to personal social accounts","Use individual credentials and lock the screen when away","Leave records open in public areas"],"answer":2,"explanation":"Access controls and screen locking protect confidentiality and traceability.","topic":"Health information","difficulty":"Easy"},{"id":"PARA-089","question":"A basic health record should use standard units because they:","options":["Replace calibration","Reduce ambiguity and support consistent communication","Make values harder to compare","Eliminate the need for identifiers"],"answer":1,"explanation":"Standard units improve clarity; follow the laboratory or clinical reporting standard.","topic":"Health information","difficulty":"Easy"},{"id":"PARA-090","question":"The purpose of a patient complaint process is to:","options":["Replace clinical documentation","Discourage patients from speaking","Provide a safe route for feedback, resolution and service improvement","Guarantee that every complaint is invalid"],"answer":2,"explanation":"A clear complaints pathway supports patient rights and quality improvement.","topic":"Patient rights","difficulty":"Moderate"},{"id":"PARA-091","question":"The term 'aseptic technique' refers to practices intended to:","options":["Measure oxygen saturation","Prevent contamination by microorganisms","Replace all cleaning","Increase microbial growth"],"answer":1,"explanation":"Aseptic technique helps prevent contamination during procedures and handling.","topic":"Infection prevention","difficulty":"Easy"},{"id":"PARA-092","question":"A healthcare worker should remove gloves:","options":["After touching clean supplies with contaminated gloves","After the task and before moving to another patient or clean task","Only at the end of the shift","Never"],"answer":1,"explanation":"Gloves are task-specific and do not replace hand hygiene; remove and perform hand hygiene appropriately.","topic":"PPE","difficulty":"Easy"},{"id":"PARA-093","question":"The safest way to dispose of a broken contaminated glass slide is to:","options":["Place it in a regular paper bin","Pick it up with bare hands","Use the designated sharps or puncture-resistant waste stream","Wrap it in a tissue only"],"answer":2,"explanation":"Contaminated broken glass is a sharps hazard and must enter the designated waste stream.","topic":"Biomedical waste","difficulty":"Moderate"},{"id":"PARA-094","question":"Why should a blood collection tourniquet generally not remain on longer than necessary?","options":["It prevents all bruising","It increases blood oxygen in the tube","It sterilises the skin","Prolonged stasis can alter some measured analytes"],"answer":3,"explanation":"Prolonged tourniquet time can cause haemoconcentration and affect some measurements.","topic":"Phlebotomy","difficulty":"Easy"},{"id":"PARA-095","question":"After venepuncture, a used needle should be:","options":["Left on the trolley","Carried in a pocket","Recapped with two hands","Disposed of immediately in the approved sharps container without recapping"],"answer":3,"explanation":"Immediate disposal without recapping reduces needlestick risk.","topic":"Phlebotomy","difficulty":"Easy"},{"id":"PARA-096","question":"The primary purpose of a patient's medical history before imaging is to:","options":["Replace image review","Identify relevant risks and choose an appropriate protocol","Determine the patient's exam score","Avoid asking for consent"],"answer":1,"explanation":"History and screening inform safe imaging, contrast and radiation decisions.","topic":"Radiology safety","difficulty":"Moderate"},{"id":"PARA-097","question":"An ultrasound image is produced using:","options":["X-rays","High-frequency sound waves","Gamma rays","Visible light only"],"answer":1,"explanation":"Ultrasound uses reflected sound waves to create images.","topic":"Imaging","difficulty":"Easy"},{"id":"PARA-098","question":"MRI primarily uses:","options":["Ionising X-rays","Strong magnetic fields and radiofrequency pulses","Ultraviolet radiation","Visible lasers"],"answer":1,"explanation":"MRI uses magnetic fields and radiofrequency energy rather than ionising X-rays.","topic":"Imaging","difficulty":"Easy"},{"id":"PARA-099","question":"Which practice reduces the risk of an MRI projectile accident?","options":["Use a magnet to test on the patient","Ignore implants","Allow all metal objects","Screen patients and remove ferromagnetic objects from the controlled area"],"answer":3,"explanation":"MR safety screening identifies implants and ferromagnetic objects before entry.","topic":"Imaging safety","difficulty":"Moderate"},{"id":"PARA-100","question":"The main function of a dialysis machine is to:","options":["Perform lung ventilation","Produce insulin","Measure bone density","Support removal of waste products and excess fluid from blood"],"answer":3,"explanation":"Dialysis uses a semipermeable membrane and dialysis fluid to remove selected solutes and fluid.","topic":"Dialysis","difficulty":"Easy"}]},"nursing":{"label":"Nursing","description":"First-year B.Sc. Nursing foundation topics.","questions":[{"id":"NURS-001","question":"Which action is the best routine way to reduce the spread of microorganisms between patients?","options":["Wear the same gloves between patients","Perform hand hygiene at the recommended moments","Clean hands only at the end of a shift","Use perfume after every contact"],"answer":1,"explanation":"Hand hygiene is a core standard precaution; gloves do not replace it.","topic":"Nursing foundation","difficulty":"Easy"},{"id":"NURS-002","question":"Before providing care, a nurse should confirm patient identity using:","options":["Bed number alone","Room number alone","A family member's guess","At least two approved identifiers"],"answer":3,"explanation":"Two approved identifiers reduce wrong-patient errors.","topic":"Patient safety","difficulty":"Easy"},{"id":"NURS-003","question":"Which statement best describes a therapeutic nurse-patient relationship?","options":["It is professional, purposeful and centred on the patient's needs","It is based on personal friendship","It encourages dependence on the nurse","It allows sharing other patients' information"],"answer":0,"explanation":"Therapeutic relationships maintain professional boundaries and focus on patient welfare.","topic":"Communication","difficulty":"Moderate"},{"id":"NURS-004","question":"The normal adult resting respiratory rate is commonly about:","options":["2-5 breaths per minute","50-60 breaths per minute","12-20 breaths per minute","30-45 breaths per minute"],"answer":2,"explanation":"A common adult reference range is 12-20 breaths/minute; interpret with clinical context.","topic":"Vital signs","difficulty":"Easy"},{"id":"NURS-005","question":"The radial pulse is usually palpated at the:","options":["Side of the neck","Wrist on the thumb side","Back of the knee","Ankle behind the medial malleolus"],"answer":1,"explanation":"The radial artery is accessible at the wrist near the base of the thumb.","topic":"Vital signs","difficulty":"Easy"},{"id":"NURS-006","question":"A blood pressure reading contains which two values?","options":["Systolic and diastolic pressures","Pulse and temperature","Height and weight","Oxygen and carbon dioxide"],"answer":0,"explanation":"Systolic pressure is the peak arterial pressure during contraction; diastolic is the pressure during relaxation.","topic":"Vital signs","difficulty":"Moderate"},{"id":"NURS-007","question":"Which position is commonly used to help a patient breathe more comfortably when short of breath, if tolerated?","options":["Trendelenburg for every patient","Lithotomy","Upright or semi-Fowler's position","Flat prone with face down"],"answer":2,"explanation":"Upright positioning can support chest expansion; assess and follow care instructions.","topic":"Patient positioning","difficulty":"Easy"},{"id":"NURS-008","question":"The purpose of a bed bath is primarily to:","options":["Replace all mobility","Diagnose infection","Prevent the need for nutrition","Maintain hygiene, comfort and skin assessment when a patient cannot bathe independently"],"answer":3,"explanation":"A bed bath supports hygiene and provides an opportunity to observe skin condition and comfort.","topic":"Personal hygiene","difficulty":"Easy"},{"id":"NURS-009","question":"When making an occupied bed, the nurse should prioritise:","options":["Leaving side rails unmanaged","Patient safety, privacy, alignment and comfort","Speed over safety","Exposing the patient unnecessarily"],"answer":1,"explanation":"Safe bed-making protects dignity and reduces falls and strain.","topic":"Basic nursing care","difficulty":"Moderate"},{"id":"NURS-010","question":"Which nutrient is the body's main readily available energy source?","options":["Vitamin C","Water","Carbohydrate","Iron"],"answer":2,"explanation":"Carbohydrates are a major energy source; energy also comes from fats and proteins.","topic":"Nutrition","difficulty":"Easy"},{"id":"NURS-011","question":"Which vitamin is important for normal blood clotting?","options":["Vitamin K","Vitamin D","Vitamin B1","Vitamin C"],"answer":0,"explanation":"Vitamin K is needed for synthesis of several clotting factors.","topic":"Nutrition","difficulty":"Easy"},{"id":"NURS-012","question":"Which mineral is a key component of haemoglobin?","options":["Fluoride","Sodium","Iodine","Iron"],"answer":3,"explanation":"Iron in haemoglobin binds oxygen.","topic":"Nutrition","difficulty":"Moderate"},{"id":"NURS-013","question":"A balanced diet generally includes:","options":["Only fruit juice","Only protein supplements","Only carbohydrates","A variety of foods supplying energy, protein, fats, vitamins, minerals and fibre"],"answer":3,"explanation":"A balanced dietary pattern provides essential macro- and micronutrients and adequate fluids.","topic":"Nutrition","difficulty":"Easy"},{"id":"NURS-014","question":"Which food is a good plant-based source of protein?","options":["Lentils or pulses","Cooking oil","Refined sugar","Salt"],"answer":0,"explanation":"Pulses provide plant protein and fibre.","topic":"Nutrition","difficulty":"Easy"},{"id":"NURS-015","question":"Which organ is primarily responsible for most nutrient absorption?","options":["Oesophagus","Urinary bladder","Small intestine","Trachea"],"answer":2,"explanation":"The small intestine has villi and microvilli that provide a large absorptive surface.","topic":"Digestive system","difficulty":"Moderate"},{"id":"NURS-016","question":"Which chamber of the heart pumps oxygenated blood to the body?","options":["Right atrium","Right ventricle","Left ventricle","Left atrium"],"answer":2,"explanation":"The left ventricle pumps blood into the aorta and systemic circulation.","topic":"Cardiovascular","difficulty":"Easy"},{"id":"NURS-017","question":"Which valve is between the left atrium and left ventricle?","options":["Tricuspid valve","Mitral valve","Aortic valve","Pulmonary valve"],"answer":1,"explanation":"The mitral (bicuspid) valve separates the left atrium and left ventricle.","topic":"Cardiovascular","difficulty":"Easy"},{"id":"NURS-018","question":"The primary function of red blood cells is to:","options":["Produce insulin","Digest dietary fat","Transport oxygen using haemoglobin","Form urine"],"answer":2,"explanation":"Red blood cells carry oxygen and some carbon dioxide.","topic":"Blood","difficulty":"Moderate"},{"id":"NURS-019","question":"Which component of blood helps defend against infection?","options":["Platelets","Red blood cells","White blood cells","Plasma water only"],"answer":2,"explanation":"White blood cells take part in immune defence.","topic":"Blood","difficulty":"Easy"},{"id":"NURS-020","question":"Which organ filters blood and forms urine?","options":["Kidney","Lung","Stomach","Spleen"],"answer":0,"explanation":"The kidneys regulate fluid and electrolyte balance and produce urine.","topic":"Renal","difficulty":"Easy"},{"id":"NURS-021","question":"Which hormone lowers blood glucose by promoting uptake and storage?","options":["Cortisol only","Adrenaline","Insulin","Glucagon"],"answer":2,"explanation":"Insulin promotes glucose uptake in several tissues and supports storage as glycogen and fat.","topic":"Endocrine","difficulty":"Moderate"},{"id":"NURS-022","question":"The basic structural unit of the nervous system is the:","options":["Nephron","Osteon","Alveolus","Neuron"],"answer":3,"explanation":"Neurons receive and transmit electrical and chemical signals.","topic":"Nervous system","difficulty":"Easy"},{"id":"NURS-023","question":"Which structure carries air from the larynx toward the bronchi?","options":["Aorta","Oesophagus","Ureter","Trachea"],"answer":3,"explanation":"The trachea connects the larynx to the main bronchi.","topic":"Respiratory","difficulty":"Easy"},{"id":"NURS-024","question":"Which of the following is an example of a hinge joint?","options":["Hip","Elbow","Shoulder","Atlanto-axial joint"],"answer":1,"explanation":"The elbow mainly permits flexion and extension, typical of a hinge joint.","topic":"Musculoskeletal","difficulty":"Moderate"},{"id":"NURS-025","question":"The main function of the skin is to:","options":["Produce red blood cells in adults","Pump blood","Filter urine","Provide a protective barrier and help regulate temperature"],"answer":3,"explanation":"Skin protects against injury and microbes and contributes to temperature regulation.","topic":"Integumentary","difficulty":"Easy"},{"id":"NURS-026","question":"Which position is commonly used for a patient undergoing a rectal examination?","options":["Prone with arms overhead","Standing on one foot","High Fowler's only","Left lateral (Sims') position"],"answer":3,"explanation":"Left lateral positioning is commonly used for selected rectal examinations, subject to clinical direction.","topic":"Patient positioning","difficulty":"Easy"},{"id":"NURS-027","question":"The first step before administering a medication is to:","options":["Ask another patient","Assume the previous dose was missed","Verify the order, patient identity and relevant medication checks","Prepare it without checking the chart"],"answer":2,"explanation":"Medication administration requires verified orders and patient/medicine checks under policy.","topic":"Medication safety","difficulty":"Moderate"},{"id":"NURS-028","question":"Which route delivers a medication under the tongue?","options":["Intramuscular","Sublingual","Rectal","Intradermal"],"answer":1,"explanation":"Sublingual medicines are placed under the tongue for absorption through oral mucosa.","topic":"Medication basics","difficulty":"Easy"},{"id":"NURS-029","question":"A medication allergy should be:","options":["Shared only verbally with visitors","Clearly documented and checked before medication administration","Removed from the record without review","Ignored if the medicine is common"],"answer":1,"explanation":"Allergy information is a key safety check and must be visible to the care team.","topic":"Medication safety","difficulty":"Easy"},{"id":"NURS-030","question":"The abbreviation 'PRN' generally means:","options":["Twice daily","As needed","Before meals","Immediately after surgery"],"answer":1,"explanation":"PRN indicates a medicine is given as needed within the prescribed limits.","topic":"Medication terminology","difficulty":"Moderate"},{"id":"NURS-031","question":"Which is an appropriate action after medication administration?","options":["Document before giving it as if already given","Document the medicine, dose, route, time and relevant response according to policy","Ask the patient to chart it","Leave the record blank"],"answer":1,"explanation":"Timely documentation supports continuity and safe medication reconciliation.","topic":"Documentation","difficulty":"Easy"},{"id":"NURS-032","question":"The purpose of informed consent is to:","options":["Permit a procedure without choice","Support a voluntary, informed decision by a person with decision-making capacity","Replace explanation","Transfer all responsibility to the nurse"],"answer":1,"explanation":"Consent requires understandable information, voluntariness and capacity, consistent with applicable rules.","topic":"Ethics","difficulty":"Easy"},{"id":"NURS-033","question":"Patient confidentiality means:","options":["Discussing cases in public areas","Never sharing information with the care team","Posting updates online without permission","Protecting personal health information from unauthorised access or disclosure"],"answer":3,"explanation":"Confidentiality allows appropriate care-related sharing but prevents unauthorised disclosure.","topic":"Ethics","difficulty":"Moderate"},{"id":"NURS-034","question":"When a patient expresses fear, the most therapeutic initial response is to:","options":["Change the subject immediately","Tell the patient not to worry","Listen without judgement and invite the patient to explain the concern","Criticise the fear"],"answer":2,"explanation":"Active listening and empathy help patients communicate concerns.","topic":"Communication","difficulty":"Easy"},{"id":"NURS-035","question":"A nurse uses teach-back when they:","options":["Test the patient's memory publicly","Give more leaflets without discussion","Ask the patient to explain instructions in their own words","Ask only 'Do you understand?'"],"answer":2,"explanation":"Teach-back checks how clearly information was communicated and identifies the need to explain again.","topic":"Health education","difficulty":"Easy"},{"id":"NURS-036","question":"A therapeutic communication technique is:","options":["Giving false reassurance","Using open-ended questions","Changing the topic whenever emotion appears","Using judgemental labels"],"answer":1,"explanation":"Open-ended questions encourage patients to describe their experiences.","topic":"Communication","difficulty":"Moderate"},{"id":"NURS-037","question":"The chain of infection includes a susceptible host. One way to interrupt transmission is to:","options":["Reuse contaminated gloves","Skip environmental cleaning","Perform hand hygiene and follow appropriate precautions","Share unclean equipment"],"answer":2,"explanation":"Hand hygiene and appropriate precautions interrupt transmission routes.","topic":"Microbiology","difficulty":"Easy"},{"id":"NURS-038","question":"The five moments for hand hygiene include before touching a patient and:","options":["Only after meals","Only when hands look dirty","Only before entering the hospital","After touching patient surroundings"],"answer":3,"explanation":"WHO's five moments include before patient contact, before clean/aseptic procedure, after body-fluid exposure risk, after patient contact and after touching patient surroundings.","topic":"Infection prevention","difficulty":"Easy"},{"id":"NURS-039","question":"Sterilisation is intended to:","options":["Clean only skin","Destroy all forms of viable microbial life, including spores","Reduce odour","Remove only visible dirt"],"answer":1,"explanation":"Sterilisation is a validated process that eliminates all forms of microbial life.","topic":"Infection prevention","difficulty":"Moderate"},{"id":"NURS-040","question":"Which PPE is used to protect the hands when exposure to blood or body fluids is anticipated?","options":["Gloves","Apron only","Shoe covers only","Cap only"],"answer":0,"explanation":"Gloves are selected based on anticipated contact; hand hygiene is still required.","topic":"PPE","difficulty":"Easy"},{"id":"NURS-041","question":"Used needles should be discarded:","options":["On the bedside table","After recapping with both hands","Immediately into a puncture-resistant sharps container","In an ordinary waste bin"],"answer":2,"explanation":"Prompt disposal without recapping reduces needlestick injury risk.","topic":"Biomedical waste","difficulty":"Easy"},{"id":"NURS-042","question":"The most appropriate way to handle a contaminated dressing is to:","options":["Dispose of it in the designated biomedical waste stream","Place it with clean linen","Put it in a personal bag","Leave it on the floor"],"answer":0,"explanation":"Segregate infectious waste at the point of generation according to current local rules.","topic":"Biomedical waste","difficulty":"Moderate"},{"id":"NURS-043","question":"A patient with a suspected airborne infection may require:","options":["Appropriate isolation and respiratory protection based on protocol","An open shared waiting area without assessment","No precautions if afebrile","Shared personal equipment"],"answer":0,"explanation":"Transmission-based precautions are added according to the suspected route and current infection-control guidance.","topic":"Isolation precautions","difficulty":"Easy"},{"id":"NURS-044","question":"Which action is correct when removing gloves?","options":["Touch the outside with clean hands","Remove them without touching bare skin with the contaminated outer surface","Snap them toward the face","Wash and reuse disposable gloves"],"answer":1,"explanation":"Safe glove removal avoids contaminating hands; perform hand hygiene afterward.","topic":"PPE","difficulty":"Easy"},{"id":"NURS-045","question":"A pressure injury risk increases when a patient has:","options":["Prolonged pressure and reduced mobility","Frequent safe repositioning","Adequate skin assessment","Good nutrition and movement"],"answer":0,"explanation":"Unrelieved pressure and shear can injure tissue, especially in immobile patients.","topic":"Skin integrity","difficulty":"Moderate"},{"id":"NURS-046","question":"A common purpose of changing the patient's position regularly is to:","options":["Prevent all infections by itself","Reduce prolonged pressure and support comfort","Replace hydration","Increase pressure on one area"],"answer":1,"explanation":"Repositioning supports comfort and pressure injury prevention as part of an individual care plan.","topic":"Basic nursing care","difficulty":"Easy"},{"id":"NURS-047","question":"Which observation should be included when assessing a wound?","options":["Location, size, tissue appearance, drainage and surrounding skin","Only the colour of the dressing packet","The nurse's personal opinion","Only the patient's room number"],"answer":0,"explanation":"Structured wound assessment documents measurable features and changes over time.","topic":"Wound care","difficulty":"Easy"},{"id":"NURS-048","question":"The purpose of intake and output monitoring is to:","options":["Measure hearing","Track fluid balance","Record sleep only","Estimate muscle power"],"answer":1,"explanation":"Fluid intake and output help assess hydration and renal/cardiovascular status.","topic":"Fluid balance","difficulty":"Moderate"},{"id":"NURS-049","question":"Which symptom may indicate dehydration?","options":["Dry mucous membranes and reduced urine output","Increased urine output in every case","Improved skin turgor","Excessive tear production only"],"answer":0,"explanation":"Dry mucosa and reduced urine output can be signs of dehydration; assessment must consider context.","topic":"Fluid balance","difficulty":"Easy"},{"id":"NURS-050","question":"A balanced nursing care plan should include:","options":["Only the medicine list","Only the diagnosis","Assessment findings, nursing problems, goals, interventions and evaluation","Unrelated personal comments"],"answer":2,"explanation":"The nursing process links assessment, planning, implementation and evaluation.","topic":"Nursing process","difficulty":"Easy"},{"id":"NURS-051","question":"The nursing process is commonly represented as:","options":["Assessment, diagnosis, planning, implementation and evaluation","Admission, billing, discharge, audit, claim","Plan, discharge, forget, reopen, bill","Observe, guess, prescribe, ignore, close"],"answer":0,"explanation":"ADPIE is a common framework for organising nursing care.","topic":"Nursing process","difficulty":"Moderate"},{"id":"NURS-052","question":"Which statement about pain assessment is most appropriate?","options":["Ignore pain if vital signs are normal","Ask visitors to decide","Use a validated scale and consider the patient's own report","Assume pain from appearance alone"],"answer":2,"explanation":"Pain is subjective; patient report and an appropriate scale guide assessment.","topic":"Assessment","difficulty":"Easy"},{"id":"NURS-053","question":"A nurse should report a sudden deterioration in a patient's condition:","options":["Only if a family member requests it","Only in the discharge summary","Promptly through the escalation pathway","At the next routine round only"],"answer":2,"explanation":"Timely escalation enables assessment and intervention by the appropriate team.","topic":"Patient safety","difficulty":"Easy"},{"id":"NURS-054","question":"Which action supports prevention of falls?","options":["Leave wet floors unmarked","Keep frequently used items within reach and maintain a clear pathway","Encourage unassisted transfers despite risk","Keep call bell out of reach"],"answer":1,"explanation":"Environmental safety and individual risk-based measures reduce falls.","topic":"Patient safety","difficulty":"Moderate"},{"id":"NURS-055","question":"A patient's right to privacy is supported by:","options":["Inviting visitors without consent","Leaving the patient exposed","Closing curtains or doors during personal care when appropriate","Discussing details in a public corridor"],"answer":2,"explanation":"Privacy and dignity should be protected during care and communication.","topic":"Ethics","difficulty":"Easy"},{"id":"NURS-056","question":"Which response best supports a patient who speaks a different language?","options":["Ask a child to interpret every sensitive issue","Guess what the patient means","Avoid communicating","Use an approved interpreter or communication support"],"answer":3,"explanation":"Qualified interpretation improves accuracy, understanding and patient autonomy.","topic":"Communication","difficulty":"Easy"},{"id":"NURS-057","question":"Which principle should guide safe lifting and transfer of a patient?","options":["Assess the patient and use appropriate equipment and assistance","Lift alone regardless of weight","Twist while lifting","Pull by the arms"],"answer":0,"explanation":"Risk assessment, safe body mechanics and transfer aids protect patient and staff.","topic":"Ergonomics","difficulty":"Moderate"},{"id":"NURS-058","question":"A nursing note should be written:","options":["Using unexplained slang","In advance before care is delivered","With unverified assumptions","Promptly, factually and legibly according to policy"],"answer":3,"explanation":"Accurate and timely records support continuity and legal accountability.","topic":"Documentation","difficulty":"Easy"},{"id":"NURS-059","question":"A nurse observes a medication error. The priority is to:","options":["Wait until discharge","Hide the error","Assess the patient, notify the appropriate clinician and follow reporting policy","Alter the record to remove evidence"],"answer":2,"explanation":"Patient assessment and timely escalation are priorities; reporting supports learning and safety.","topic":"Medication safety","difficulty":"Easy"},{"id":"NURS-060","question":"Which term refers to a person's ability to understand and make decisions about care?","options":["Decision-making capacity","Blood pressure","Pulse pressure","Body mass index"],"answer":0,"explanation":"Capacity is decision-specific and relates to understanding, retaining, using or weighing information and communicating a choice.","topic":"Ethics","difficulty":"Moderate"},{"id":"NURS-061","question":"Which vitamin deficiency is associated with impaired collagen formation and poor wound healing?","options":["Vitamin K","Vitamin D","Vitamin B12","Vitamin C"],"answer":3,"explanation":"Vitamin C supports collagen synthesis and tissue repair.","topic":"Nutrition","difficulty":"Easy"},{"id":"NURS-062","question":"Which nutrient is most important for tissue growth and repair?","options":["Sodium chloride","Water only","Protein","Dietary fibre only"],"answer":2,"explanation":"Proteins provide amino acids needed for growth, maintenance and tissue repair.","topic":"Nutrition","difficulty":"Easy"},{"id":"NURS-063","question":"Which food choice is most appropriate as a source of dietary fibre?","options":["Butter","Clear soda","Refined sugar syrup","Whole grains and vegetables"],"answer":3,"explanation":"Whole grains and vegetables provide dietary fibre that supports bowel health.","topic":"Nutrition","difficulty":"Moderate"},{"id":"NURS-064","question":"The primary function of the large intestine is to:","options":["Filter blood","Exchange oxygen","Produce bile","Absorb water and electrolytes and form faeces"],"answer":3,"explanation":"The colon absorbs water and electrolytes and compacts intestinal contents.","topic":"Digestive system","difficulty":"Easy"},{"id":"NURS-065","question":"Which structure connects the mouth to the stomach?","options":["Urethra","Oesophagus","Ureter","Trachea"],"answer":1,"explanation":"The oesophagus carries swallowed food to the stomach.","topic":"Digestive system","difficulty":"Easy"},{"id":"NURS-066","question":"Which blood group system is most commonly used for routine ABO blood grouping?","options":["Only positive and negative","Alpha and beta only","I, II and III","A, B, AB and O"],"answer":3,"explanation":"ABO grouping classifies red cells according to A and B antigens; Rh is a separate system.","topic":"Blood","difficulty":"Moderate"},{"id":"NURS-067","question":"Which blood component is the liquid portion that carries cells and dissolved substances?","options":["Platelets","Erythrocytes","Neutrophils","Plasma"],"answer":3,"explanation":"Plasma is the fluid matrix containing water, proteins, electrolytes and other solutes.","topic":"Blood","difficulty":"Easy"},{"id":"NURS-068","question":"Which organ produces bile?","options":["Pancreas","Liver","Kidney","Spleen"],"answer":1,"explanation":"The liver produces bile, which is stored and concentrated in the gallbladder.","topic":"Digestive system","difficulty":"Easy"},{"id":"NURS-069","question":"Which organ stores bile before release into the small intestine?","options":["Appendix","Spleen","Urinary bladder","Gallbladder"],"answer":3,"explanation":"The gallbladder stores and concentrates bile produced by the liver.","topic":"Digestive system","difficulty":"Moderate"},{"id":"NURS-070","question":"Which part of the respiratory tract contains the vocal cords?","options":["Larynx","Bronchiole","Pleura","Alveolus"],"answer":0,"explanation":"The larynx houses the vocal folds and connects the pharynx to the trachea.","topic":"Respiratory","difficulty":"Easy"},{"id":"NURS-071","question":"The pulse felt at the wrist is produced by:","options":["Air entering the lungs","Expansion of an artery with each heartbeat","Movement of a tendon","Contraction of skeletal muscle only"],"answer":1,"explanation":"The arterial pulse is a pressure wave generated by ventricular ejection.","topic":"Cardiovascular","difficulty":"Easy"},{"id":"NURS-072","question":"Which body system includes the pituitary, thyroid and adrenal glands?","options":["Integumentary system","Skeletal system","Respiratory system","Endocrine system"],"answer":3,"explanation":"The endocrine system includes glands that secrete hormones into the circulation.","topic":"Endocrine","difficulty":"Moderate"},{"id":"NURS-073","question":"The main function of insulin is to:","options":["Transport oxygen","Increase urine production directly","Raise blood glucose by breaking glycogen","Lower blood glucose by promoting uptake and storage"],"answer":3,"explanation":"Insulin supports glucose uptake in responsive tissues and storage pathways.","topic":"Endocrine","difficulty":"Easy"},{"id":"NURS-074","question":"Which hormone is commonly associated with the body's response to stress?","options":["Melatonin only","Insulin","Calcitonin","Adrenaline (epinephrine)"],"answer":3,"explanation":"Adrenaline is released from the adrenal medulla and supports the fight-or-flight response.","topic":"Endocrine","difficulty":"Easy"},{"id":"NURS-075","question":"Which part of the brain helps coordinate movement and balance?","options":["Pituitary gland","Cerebellum","Medulla only","Corpus callosum only"],"answer":1,"explanation":"The cerebellum contributes to coordination, posture and balance.","topic":"Nervous system","difficulty":"Moderate"},{"id":"NURS-076","question":"Which structure connects the brain with the spinal cord?","options":["Brainstem","Patella","Pancreas","Tibia"],"answer":0,"explanation":"The brainstem links major brain regions with the spinal cord and contains vital centres.","topic":"Nervous system","difficulty":"Easy"},{"id":"NURS-077","question":"Which type of muscle is found in the wall of the intestine?","options":["Smooth muscle","Skeletal muscle","Voluntary striated muscle only","Cardiac muscle"],"answer":0,"explanation":"Smooth muscle helps propel contents through hollow organs.","topic":"Musculoskeletal","difficulty":"Easy"},{"id":"NURS-078","question":"Cardiac muscle is found in the:","options":["Tendon","Biceps","Heart","Stomach lining only"],"answer":2,"explanation":"Cardiac muscle forms the contractile myocardium.","topic":"Musculoskeletal","difficulty":"Moderate"},{"id":"NURS-079","question":"Which joint allows flexion and extension mainly in one plane?","options":["Hinge joint","Ball-and-socket joint","Plane joint","Pivot joint"],"answer":0,"explanation":"Hinge joints, such as the elbow, permit flexion and extension primarily.","topic":"Musculoskeletal","difficulty":"Easy"},{"id":"NURS-080","question":"A fracture is:","options":["A joint dislocation only","An inflammation of a tendon","A muscle contraction","A break in the continuity of a bone"],"answer":3,"explanation":"A fracture is a disruption in bone continuity.","topic":"Musculoskeletal","difficulty":"Easy"},{"id":"NURS-081","question":"Which is a common sign that a wound may be infected?","options":["Normal intact surrounding skin","A clean, dry dressing only","Improving pain and reduced redness","Increasing redness, warmth, swelling or purulent discharge"],"answer":3,"explanation":"Increasing local inflammatory signs or purulent drainage warrant clinical assessment.","topic":"Wound care","difficulty":"Moderate"},{"id":"NURS-082","question":"The purpose of a sterile dressing is to:","options":["Increase microbial growth","Protect the wound and reduce contamination","Replace wound assessment","Keep all wounds moist regardless of type"],"answer":1,"explanation":"Dressings protect wounds and manage the wound environment according to the plan.","topic":"Wound care","difficulty":"Easy"},{"id":"NURS-083","question":"Which action best prevents cross-contamination when using a stethoscope?","options":["Use it unchanged for every patient","Clean it only once a month","Store it on the floor","Clean the patient-contact surfaces between patients according to policy"],"answer":3,"explanation":"Shared patient-care equipment should be cleaned between patients using approved products.","topic":"Infection prevention","difficulty":"Easy"},{"id":"NURS-084","question":"A nurse should verify the correct patient, medicine, dose, route and time because these are part of:","options":["A discharge transport list","A nutrition chart","A radiology marker","Medication administration safety checks"],"answer":3,"explanation":"Medication safety checks reduce preventable administration errors; local policies may include additional rights.","topic":"Medication safety","difficulty":"Moderate"},{"id":"NURS-085","question":"Which is an appropriate response to a patient's question about a diagnosis outside the nurse's role?","options":["Explain what is within scope and refer the question to the responsible clinician","Promise a cure","Invent a diagnosis","Avoid documenting the concern"],"answer":0,"explanation":"Nurses should communicate within scope and facilitate access to the responsible clinician.","topic":"Professional practice","difficulty":"Easy"},{"id":"NURS-086","question":"Which action demonstrates respect for patient autonomy?","options":["Explain choices and respect an informed decision within applicable law","Make decisions without discussion","Withhold all information","Threaten the patient"],"answer":0,"explanation":"Autonomy includes supporting informed choices and respecting the patient's decision-making rights.","topic":"Ethics","difficulty":"Easy"},{"id":"NURS-087","question":"The purpose of a nursing audit is to:","options":["Punish every staff member","Replace patient assessment","Increase the number of forms only","Review care and documentation against agreed standards"],"answer":3,"explanation":"Audit compares practice with standards and identifies improvement opportunities.","topic":"Quality improvement","difficulty":"Moderate"},{"id":"NURS-088","question":"Which term describes the process of checking whether a learning or care goal has been achieved?","options":["Evaluation","Sterilisation","Handover","Admission"],"answer":0,"explanation":"Evaluation reviews outcomes against goals and informs the next care plan.","topic":"Nursing process","difficulty":"Easy"},{"id":"NURS-089","question":"Which action best promotes safe oral care for an unconscious patient?","options":["Pour large volumes of water into the mouth","Ignore oral secretions","Follow aspiration-prevention precautions and the prescribed oral-care procedure","Leave dentures loose"],"answer":2,"explanation":"Unconscious patients are at aspiration risk; oral care requires trained technique and precautions.","topic":"Basic nursing care","difficulty":"Easy"},{"id":"NURS-090","question":"A patient reports dizziness when standing. The nurse should first:","options":["Encourage rapid walking","Offer unassessed medication","Leave the patient standing","Help the patient sit or lie safely and assess according to protocol"],"answer":3,"explanation":"Preventing a fall and assessing the patient safely are immediate priorities.","topic":"Patient safety","difficulty":"Moderate"},{"id":"NURS-091","question":"Which action supports continuity of care during a shift change?","options":["Omit abnormal findings","Rely on informal conversation in a corridor","Give only the patient's name","Provide a structured handover with current status, risks and pending tasks"],"answer":3,"explanation":"A structured handover communicates essential information and responsibilities.","topic":"Communication","difficulty":"Easy"},{"id":"NURS-092","question":"Which statement best describes empathy in nursing?","options":["Understanding the patient's perspective and responding respectfully","Agreeing with every request","Avoiding emotional communication","Feeling sorry without listening"],"answer":0,"explanation":"Empathy recognises another person's perspective and supports compassionate communication.","topic":"Psychology","difficulty":"Easy"},{"id":"NURS-093","question":"A patient's health literacy refers to their ability to:","options":["Operate hospital equipment","Memorise every medical term","Find, understand and use health information and services","Read only prescription labels"],"answer":2,"explanation":"Health literacy includes accessing, understanding and using health information for decisions.","topic":"Health education","difficulty":"Moderate"},{"id":"NURS-094","question":"Which is an example of a primary prevention activity?","options":["Rehabilitation after stroke","Wound dressing after injury","Immunisation","Physiotherapy after a fracture"],"answer":2,"explanation":"Primary prevention aims to prevent disease or injury before it occurs; immunisation is an example.","topic":"Community health","difficulty":"Easy"},{"id":"NURS-095","question":"Screening for a disease in apparently healthy people is generally an example of:","options":["Secondary prevention","Post-discharge billing","Palliative care","Tertiary rehabilitation only"],"answer":0,"explanation":"Screening aims to detect disease early, a form of secondary prevention.","topic":"Community health","difficulty":"Easy"},{"id":"NURS-096","question":"Which action is appropriate when handling a patient's belongings?","options":["Leave valuables unattended","Give them to another patient","Label, document and store them according to hospital policy","Discard them without permission"],"answer":2,"explanation":"Proper handling protects property and supports trust and accountability.","topic":"Patient rights","difficulty":"Moderate"},{"id":"NURS-097","question":"The purpose of a call bell is to:","options":["Record medicines","Allow a patient to request assistance","Open the medicine cabinet","Measure oxygen saturation"],"answer":1,"explanation":"A call bell allows patients to summon staff and should be kept accessible.","topic":"Patient safety","difficulty":"Easy"},{"id":"NURS-098","question":"A nurse should assess pain after an intervention to:","options":["Evaluate whether the intervention helped and whether further action is needed","Replace all vital signs","Confirm the patient is asleep","Avoid documenting response"],"answer":0,"explanation":"Reassessment measures response and informs ongoing care.","topic":"Assessment","difficulty":"Easy"},{"id":"NURS-099","question":"The best approach when providing care to a patient from a different cultural background is to:","options":["Assume all family members make decisions","Ignore language and beliefs","Use stereotypes","Ask about preferences rather than making assumptions"],"answer":3,"explanation":"Culturally safe care is individualised and respectful.","topic":"Cultural competence","difficulty":"Moderate"},{"id":"NURS-100","question":"Which of the following is a common route of transmission for many respiratory infections?","options":["Only contaminated food","Respiratory particles and contaminated hands or surfaces, depending on the pathogen","Only inherited genes","Only insect bites"],"answer":1,"explanation":"Transmission routes vary by pathogen and can include inhaled particles and contact routes.","topic":"Microbiology","difficulty":"Easy"}]},"mbbs_1st_year":{"label":"MBBS 1st Year","description":"NMC CBME Phase I: Anatomy, Physiology, Biochemistry and professional foundations.","questions":[{"id":"MBBS-001","question":"The standard anatomical position places the palms:","options":["Facing downwards","Facing posteriorly","Facing medially with elbows flexed","Facing anteriorly"],"answer":3,"explanation":"In standard anatomical position, the palms face forward and the thumbs point laterally.","topic":"General anatomy","difficulty":"Easy"},{"id":"MBBS-002","question":"Which plane divides the body into anterior and posterior parts?","options":["Transverse plane","Median plane","Coronal (frontal) plane","Sagittal plane"],"answer":2,"explanation":"The coronal plane separates front and back portions of the body.","topic":"General anatomy","difficulty":"Easy"},{"id":"MBBS-003","question":"A structure nearer the point of attachment of a limb is described as:","options":["Superficial","Lateral","Distal","Proximal"],"answer":3,"explanation":"Proximal means nearer the trunk or point of origin; distal means farther away.","topic":"General anatomy","difficulty":"Moderate"},{"id":"MBBS-004","question":"Which type of epithelium is best suited for rapid diffusion in alveoli?","options":["Pseudostratified ciliated epithelium","Stratified squamous epithelium","Transitional epithelium","Simple squamous epithelium"],"answer":3,"explanation":"Thin simple squamous cells facilitate gas diffusion across alveolar walls.","topic":"Histology","difficulty":"Easy"},{"id":"MBBS-005","question":"Which cell junction helps prevent leakage between adjacent epithelial cells?","options":["Gap junction","Desmosome only","Tight junction","Hemidesmosome"],"answer":2,"explanation":"Tight junctions seal the space between adjacent cells and regulate paracellular passage.","topic":"Histology","difficulty":"Easy"},{"id":"MBBS-006","question":"The basic structural unit of compact bone is the:","options":["Lobule","Sarcomere","Nephron","Osteon (Haversian system)"],"answer":3,"explanation":"Compact bone is organised into osteons containing concentric lamellae around central canals.","topic":"Histology","difficulty":"Moderate"},{"id":"MBBS-007","question":"Which cells are primarily responsible for bone formation?","options":["Osteoclasts","Fibroblasts","Chondrocytes","Osteoblasts"],"answer":3,"explanation":"Osteoblasts form bone matrix; osteoclasts resorb bone.","topic":"Histology","difficulty":"Easy"},{"id":"MBBS-008","question":"Which cell type forms myelin in the central nervous system?","options":["Schwann cell","Microglial cell","Astrocyte","Oligodendrocyte"],"answer":3,"explanation":"Oligodendrocytes myelinate CNS axons; Schwann cells myelinate peripheral nerves.","topic":"Neuroanatomy","difficulty":"Easy"},{"id":"MBBS-009","question":"The functional unit of skeletal muscle contraction is the:","options":["Alveolus","Osteon","Nephron","Sarcomere"],"answer":3,"explanation":"Sarcomeres are repeating contractile units containing actin and myosin filaments.","topic":"Muscle","difficulty":"Moderate"},{"id":"MBBS-010","question":"Which protein binds calcium in skeletal muscle to initiate contraction?","options":["Myoglobin","Albumin","Troponin C","Collagen"],"answer":2,"explanation":"Calcium binding to troponin C shifts tropomyosin and exposes actin binding sites.","topic":"Muscle physiology","difficulty":"Easy"},{"id":"MBBS-011","question":"The shoulder joint is classified as a:","options":["Hinge joint","Fibrous joint","Pivot joint","Ball-and-socket synovial joint"],"answer":3,"explanation":"The glenohumeral joint permits movement in multiple axes.","topic":"Joints","difficulty":"Easy"},{"id":"MBBS-012","question":"Which bone forms the forehead and part of the roof of the orbit?","options":["Mandible","Frontal bone","Temporal bone","Occipital bone"],"answer":1,"explanation":"The frontal bone forms the forehead and contributes to the orbital roof.","topic":"Osteology","difficulty":"Moderate"},{"id":"MBBS-013","question":"The foramen magnum is located in the:","options":["Frontal bone","Occipital bone","Maxilla","Sphenoid bone"],"answer":1,"explanation":"The foramen magnum is the large opening in the occipital bone for the medulla and associated structures.","topic":"Osteology","difficulty":"Easy"},{"id":"MBBS-014","question":"The median nerve passes through the:","options":["Cubital tunnel only","Greater sciatic foramen","Carpal tunnel","Tarsal tunnel"],"answer":2,"explanation":"The median nerve passes through the carpal tunnel at the wrist.","topic":"Neuroanatomy","difficulty":"Easy"},{"id":"MBBS-015","question":"The femoral artery is a continuation of the:","options":["Internal iliac artery","Popliteal artery","External iliac artery","Anterior tibial artery"],"answer":2,"explanation":"The external iliac artery becomes the femoral artery after passing deep to the inguinal ligament.","topic":"Angiology","difficulty":"Moderate"},{"id":"MBBS-016","question":"Which chamber receives systemic venous blood through the venae cavae?","options":["Left ventricle","Right ventricle","Left atrium","Right atrium"],"answer":3,"explanation":"The superior and inferior venae cavae drain into the right atrium.","topic":"Cardiovascular anatomy","difficulty":"Easy"},{"id":"MBBS-017","question":"The sinoatrial node is normally located in the:","options":["Interventricular septum near the apex","Right atrium near the opening of the superior vena cava","Left ventricle","Coronary sinus"],"answer":1,"explanation":"The SA node lies in the right atrial wall near the SVC opening and normally initiates sinus rhythm.","topic":"Cardiac physiology","difficulty":"Easy"},{"id":"MBBS-018","question":"Which valve prevents backflow from the left ventricle into the left atrium?","options":["Mitral valve","Tricuspid valve","Pulmonary valve","Aortic valve"],"answer":0,"explanation":"The mitral valve closes during ventricular systole to prevent regurgitation into the left atrium.","topic":"Cardiovascular anatomy","difficulty":"Moderate"},{"id":"MBBS-019","question":"The functional exchange unit of the lung is the:","options":["Alveolus","Terminal bronchiole","Pleural cavity","Trachea"],"answer":0,"explanation":"Alveoli provide a large surface area and thin barrier for gas exchange.","topic":"Respiratory anatomy","difficulty":"Easy"},{"id":"MBBS-020","question":"The right lung normally has how many lobes?","options":["One","Two","Three","Four"],"answer":2,"explanation":"The right lung has superior, middle and inferior lobes; the left has two.","topic":"Respiratory anatomy","difficulty":"Easy"},{"id":"MBBS-021","question":"The nephron begins with the:","options":["Distal convoluted tubule","Loop of Henle","Renal corpuscle","Collecting duct"],"answer":2,"explanation":"The renal corpuscle consists of the glomerulus and Bowman's capsule, where filtration begins.","topic":"Renal anatomy","difficulty":"Moderate"},{"id":"MBBS-022","question":"The thyroid gland primarily secretes:","options":["Cortisol and aldosterone","ADH and oxytocin","T3 and T4","Insulin and glucagon"],"answer":2,"explanation":"The thyroid secretes thyroid hormones T3 and T4, which regulate metabolism and development.","topic":"Endocrine","difficulty":"Easy"},{"id":"MBBS-023","question":"The pituitary gland is connected to the hypothalamus by the:","options":["Corpus callosum","Pineal stalk","Infundibulum","Optic chiasm"],"answer":2,"explanation":"The infundibulum is the pituitary stalk connecting it to the hypothalamus.","topic":"Neuroanatomy","difficulty":"Easy"},{"id":"MBBS-024","question":"Which embryological layer gives rise to the central nervous system?","options":["Mesoderm","Endoderm","Ectoderm","Trophoblast"],"answer":2,"explanation":"The neural tube develops from ectoderm and forms the CNS.","topic":"Embryology","difficulty":"Moderate"},{"id":"MBBS-025","question":"The notochord plays an important role in:","options":["Producing bile","Forming red blood cells throughout life","Forming the placenta alone","Inducing formation of the neural plate and patterning the axial skeleton"],"answer":3,"explanation":"The notochord is an embryonic axial structure involved in neural induction and contributes to the nucleus pulposus.","topic":"Embryology","difficulty":"Easy"},{"id":"MBBS-026","question":"Which part of the cell cycle is associated with DNA replication?","options":["G1 phase","G2 phase","S phase","M phase only"],"answer":2,"explanation":"DNA synthesis occurs during the S phase of interphase.","topic":"Cell biology","difficulty":"Easy"},{"id":"MBBS-027","question":"The resting membrane potential of most neurons is primarily related to:","options":["Ion gradients and selective membrane permeability, especially to potassium","Bile secretion","Haemoglobin concentration","Calcium stored in bone"],"answer":0,"explanation":"Selective permeability to K+ and ion gradients established by transporters contribute to resting membrane potential.","topic":"Neurophysiology","difficulty":"Moderate"},{"id":"MBBS-028","question":"The main neurotransmitter released at the neuromuscular junction is:","options":["GABA","Serotonin","Acetylcholine","Dopamine"],"answer":2,"explanation":"Motor nerve terminals release acetylcholine onto nicotinic receptors at the neuromuscular junction.","topic":"Neurophysiology","difficulty":"Easy"},{"id":"MBBS-029","question":"The normal adult cardiac pacemaker is the:","options":["Bundle branches","Atrioventricular bundle","Purkinje network","Sinoatrial node"],"answer":3,"explanation":"The SA node normally initiates the cardiac impulse, setting sinus rhythm.","topic":"Cardiac physiology","difficulty":"Easy"},{"id":"MBBS-030","question":"Cardiac output is calculated as:","options":["Stroke volume divided by body temperature","Heart rate multiplied by stroke volume","Pulse pressure multiplied by oxygen saturation","Blood pressure divided by respiratory rate"],"answer":1,"explanation":"Cardiac output equals heart rate x stroke volume.","topic":"Cardiac physiology","difficulty":"Moderate"},{"id":"MBBS-031","question":"The first heart sound (S1) is mainly associated with closure of the:","options":["Coronary ostia","Mitral and tricuspid valves","Venae cavae","Aortic and pulmonary valves"],"answer":1,"explanation":"S1 occurs with closure of the atrioventricular valves at the start of ventricular systole.","topic":"Cardiac physiology","difficulty":"Easy"},{"id":"MBBS-032","question":"The main site of oxygen and carbon dioxide exchange is the:","options":["Alveolar-capillary membrane","Pleural space","Tracheal cartilage","Laryngeal inlet"],"answer":0,"explanation":"Diffusion occurs across the thin alveolar-capillary barrier.","topic":"Respiratory physiology","difficulty":"Easy"},{"id":"MBBS-033","question":"Most oxygen in arterial blood is transported:","options":["Bound to albumin","As bicarbonate","Dissolved freely in plasma","Bound to haemoglobin"],"answer":3,"explanation":"Most oxygen is carried reversibly bound to haemoglobin; a small fraction is dissolved in plasma.","topic":"Respiratory physiology","difficulty":"Moderate"},{"id":"MBBS-034","question":"The Bohr effect describes how increased carbon dioxide and hydrogen ion concentration:","options":["Prevent oxygen unloading","Convert haemoglobin to myoglobin","Increase haemoglobin affinity for oxygen","Reduce haemoglobin affinity for oxygen"],"answer":3,"explanation":"Higher CO2 and H+ shift the oxygen dissociation curve right, promoting oxygen unloading in tissues.","topic":"Respiratory physiology","difficulty":"Easy"},{"id":"MBBS-035","question":"Which lung volume remains after maximal forced expiration?","options":["Residual volume","Expiratory reserve volume","Inspiratory reserve volume","Tidal volume"],"answer":0,"explanation":"Residual volume is the air remaining after maximal expiration and cannot be exhaled voluntarily.","topic":"Respiratory physiology","difficulty":"Easy"},{"id":"MBBS-036","question":"The major extracellular cation is:","options":["Magnesium","Phosphate","Potassium","Sodium"],"answer":3,"explanation":"Sodium is the predominant cation in extracellular fluid; potassium predominates intracellularly.","topic":"Body fluids","difficulty":"Moderate"},{"id":"MBBS-037","question":"The major intracellular cation is:","options":["Bicarbonate","Chloride","Sodium","Potassium"],"answer":3,"explanation":"Potassium is the predominant intracellular cation.","topic":"Body fluids","difficulty":"Easy"},{"id":"MBBS-038","question":"The principal buffer system in blood plasma is the:","options":["Bicarbonate buffer system","Ammonia only","Haemoglobin only","Phosphate only"],"answer":0,"explanation":"The bicarbonate-carbonic acid system is a major extracellular buffer.","topic":"Acid-base physiology","difficulty":"Easy"},{"id":"MBBS-039","question":"The glomerular filtration barrier normally restricts filtration of:","options":["Water","Glucose under normal conditions","Large proteins and cells","Small ions"],"answer":2,"explanation":"The filtration barrier retains blood cells and most large proteins while allowing water and small solutes.","topic":"Renal physiology","difficulty":"Moderate"},{"id":"MBBS-040","question":"Antidiuretic hormone increases water reabsorption mainly in the:","options":["Alveoli","Proximal stomach","Glomerular capillaries","Collecting ducts"],"answer":3,"explanation":"ADH promotes aquaporin insertion in collecting duct principal cells.","topic":"Renal physiology","difficulty":"Easy"},{"id":"MBBS-041","question":"The hormone primarily responsible for increasing blood calcium by acting on bone and kidney is:","options":["Aldosterone","Melatonin","Insulin","Parathyroid hormone"],"answer":3,"explanation":"PTH increases serum calcium through actions on bone and kidney and indirectly the intestine via vitamin D.","topic":"Endocrine physiology","difficulty":"Easy"},{"id":"MBBS-042","question":"Which hormone is secreted by pancreatic beta cells?","options":["Somatostatin only","Gastrin","Glucagon","Insulin"],"answer":3,"explanation":"Pancreatic beta cells produce insulin; alpha cells produce glucagon.","topic":"Endocrine physiology","difficulty":"Moderate"},{"id":"MBBS-043","question":"The main function of thyroid hormones is to:","options":["Produce bile","Regulate metabolic activity, growth and development","Control blood clotting directly","Form antibodies"],"answer":1,"explanation":"T3 and T4 influence metabolic rate and are important for growth and development.","topic":"Endocrine physiology","difficulty":"Easy"},{"id":"MBBS-044","question":"Which blood group is commonly called the universal red-cell donor type in emergency teaching, subject to compatibility testing?","options":["B negative","O negative","A positive","AB positive"],"answer":1,"explanation":"O negative red cells lack A, B and RhD antigens, but transfusion protocols and crossmatching remain essential.","topic":"Haematology","difficulty":"Easy"},{"id":"MBBS-045","question":"The main role of platelets in haemostasis is to:","options":["Transport oxygen","Produce bile","Carry nerve impulses","Form the initial platelet plug at the site of vessel injury"],"answer":3,"explanation":"Platelet adhesion and aggregation form the primary haemostatic plug.","topic":"Haematology","difficulty":"Moderate"},{"id":"MBBS-046","question":"Which plasma protein is the major contributor to oncotic pressure?","options":["Haemoglobin","Fibrinogen","Albumin","Troponin"],"answer":2,"explanation":"Albumin is abundant and contributes substantially to plasma colloid oncotic pressure.","topic":"Haematology","difficulty":"Easy"},{"id":"MBBS-047","question":"The ABO blood group antigens are located on the:","options":["Plasma water","Red blood cell membrane","Nuclear membrane of leukocytes","Platelet nucleus"],"answer":1,"explanation":"ABO antigens are carbohydrate structures on the red-cell surface and other tissues.","topic":"Haematology","difficulty":"Easy"},{"id":"MBBS-048","question":"Which vitamin is required for gamma-carboxylation of several coagulation factors?","options":["Vitamin K","Vitamin E","Vitamin B1","Vitamin C"],"answer":0,"explanation":"Vitamin K is needed for activation of factors II, VII, IX and X and proteins C and S.","topic":"Haematology","difficulty":"Moderate"},{"id":"MBBS-049","question":"A deficiency of vitamin B12 can lead to:","options":["Night blindness only","Scurvy","Rickets only","Megaloblastic anaemia and neurological manifestations"],"answer":3,"explanation":"B12 deficiency impairs DNA synthesis and can damage myelin, producing neurological signs.","topic":"Nutrition and biochemistry","difficulty":"Easy"},{"id":"MBBS-050","question":"Vitamin D is important for:","options":["Calcium and phosphate homeostasis and bone mineralisation","Blood group antigen production","Oxygen transport","Bile synthesis only"],"answer":0,"explanation":"Vitamin D supports intestinal calcium and phosphate absorption and bone health.","topic":"Nutrition and biochemistry","difficulty":"Easy"},{"id":"MBBS-051","question":"The main storage form of carbohydrate in humans is:","options":["Albumin","Cellulose","Glycogen","Cholesterol"],"answer":2,"explanation":"Glycogen is stored primarily in liver and skeletal muscle.","topic":"Biochemistry","difficulty":"Moderate"},{"id":"MBBS-052","question":"Glycolysis takes place in the:","options":["Lysosome","Mitochondrial matrix only","Cytosol","Nucleus"],"answer":2,"explanation":"Glycolysis occurs in the cytosol and converts glucose to pyruvate or lactate.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-053","question":"The final electron acceptor in the mitochondrial electron transport chain is:","options":["Glucose","Oxygen","Carbon dioxide","Nitrogen"],"answer":1,"explanation":"Oxygen accepts electrons and is reduced to water at complex IV.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-054","question":"Which enzyme breaks down starch into smaller carbohydrates in saliva?","options":["Lipase","Trypsin","Amylase","Pepsin"],"answer":2,"explanation":"Salivary amylase begins starch digestion in the mouth.","topic":"Biochemistry","difficulty":"Moderate"},{"id":"MBBS-055","question":"Enzymes increase reaction rates mainly by:","options":["Being consumed as reactants","Increasing the temperature permanently","Lowering activation energy","Changing the final equilibrium constant"],"answer":2,"explanation":"Enzymes lower activation energy and are not consumed in the reaction.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-056","question":"A protein is made from building blocks called:","options":["Nucleotides only","Fatty acids","Amino acids","Monosaccharides"],"answer":2,"explanation":"Proteins are polymers of amino acids linked by peptide bonds.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-057","question":"DNA contains which nitrogenous base not normally found in RNA?","options":["Guanine","Uracil","Adenine","Thymine"],"answer":3,"explanation":"DNA contains thymine; RNA typically contains uracil instead.","topic":"Molecular biology","difficulty":"Moderate"},{"id":"MBBS-058","question":"The central dogma of molecular biology describes information flow primarily as:","options":["Protein to DNA to RNA","RNA to lipid to DNA","DNA to RNA to protein","Carbohydrate to DNA to protein"],"answer":2,"explanation":"Transcription transfers information from DNA to RNA; translation makes protein from mRNA.","topic":"Molecular biology","difficulty":"Easy"},{"id":"MBBS-059","question":"Which molecule is the immediate energy currency used by cells?","options":["Cholesterol","Urea","ATP","DNA"],"answer":2,"explanation":"ATP hydrolysis supplies energy for many cellular processes.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-060","question":"The urea cycle mainly helps the body:","options":["Produce oxygen in lungs","Digest cellulose","Store calcium in bone","Convert toxic ammonia into urea for excretion"],"answer":3,"explanation":"The urea cycle converts nitrogen from amino acid metabolism into urea in the liver.","topic":"Biochemistry","difficulty":"Moderate"},{"id":"MBBS-061","question":"Which lipoprotein is commonly called 'good cholesterol' because it participates in reverse cholesterol transport?","options":["Chylomicron","HDL","VLDL","LDL"],"answer":1,"explanation":"HDL participates in reverse cholesterol transport; cardiovascular risk depends on the full lipid profile.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-062","question":"Which macromolecule is the main component of cell membranes together with proteins?","options":["Glycogen","DNA","Starch","Phospholipids"],"answer":3,"explanation":"Phospholipids form the bilayer structure of biological membranes.","topic":"Cell biology","difficulty":"Easy"},{"id":"MBBS-063","question":"A buffer resists changes in pH by:","options":["Removing all water","Accepting or donating hydrogen ions","Destroying all acids","Increasing temperature"],"answer":1,"explanation":"Buffers minimise pH changes when small amounts of acid or base are added.","topic":"Biochemistry","difficulty":"Moderate"},{"id":"MBBS-064","question":"Which organ is a major site of glycogen storage and blood glucose regulation?","options":["Thyroid","Spleen","Liver","Lung"],"answer":2,"explanation":"The liver stores glycogen and helps maintain blood glucose between meals.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-065","question":"Bilirubin is mainly produced from the breakdown of:","options":["Collagen","Glucose","Haem from haemoglobin","Fatty acids"],"answer":2,"explanation":"Haem catabolism produces biliverdin and then bilirubin.","topic":"Biochemistry","difficulty":"Easy"},{"id":"MBBS-066","question":"Which laboratory practice is appropriate before handling a biological specimen?","options":["Taste the specimen","Pipette by mouth","Use risk-based PPE and follow biosafety procedures","Carry an open tube in a pocket"],"answer":2,"explanation":"Standard biosafety practices protect staff and maintain specimen integrity.","topic":"Laboratory safety","difficulty":"Moderate"},{"id":"MBBS-067","question":"AETCOM in the MBBS curriculum focuses on:","options":["Attitude, Ethics and Communication","Assessment, Examination and Course Management","Anaesthesia, Emergency and Critical Care","Anatomy, Enzymes and Clinical Medicine"],"answer":0,"explanation":"AETCOM develops professional attitude, ethics and communication competencies.","topic":"AETCOM","difficulty":"Easy"},{"id":"MBBS-068","question":"When speaking with a patient, a respectful approach includes:","options":["Interrupting frequently","Using understandable language and allowing questions","Discussing the patient in front of others without consent","Using unexplained jargon"],"answer":1,"explanation":"Patient-centred communication should be respectful, understandable and non-judgemental.","topic":"AETCOM","difficulty":"Easy"},{"id":"MBBS-069","question":"The principle of confidentiality requires a medical student to:","options":["Post case details online without consent","Discuss cases in public lifts","Protect identifiable patient information and share it only appropriately","Share patient photographs in class groups without approval"],"answer":2,"explanation":"Confidentiality is fundamental; educational use must follow consent and institutional safeguards.","topic":"AETCOM","difficulty":"Moderate"},{"id":"MBBS-070","question":"During early clinical exposure, a student should primarily:","options":["Disclose patient details publicly","Perform procedures independently without approval","Observe, communicate respectfully and learn under supervision","Prescribe medicines"],"answer":2,"explanation":"Early clinical exposure introduces patient context while maintaining supervision and role boundaries.","topic":"Early clinical exposure","difficulty":"Easy"},{"id":"MBBS-071","question":"A cadaver in anatomy teaching should be treated with:","options":["Casual handling without regard","Respect, dignity and adherence to institutional procedures","Public photography without permission","Unlabelled removal of tissue"],"answer":1,"explanation":"NMC CBME includes respect for cadavers and biologic tissue as part of professional formation.","topic":"AETCOM","difficulty":"Easy"},{"id":"MBBS-072","question":"Which of the following is an example of primary healthcare?","options":["Only intensive care in a tertiary hospital","Only highly specialised transplant surgery","Only post-mortem examination","First-contact comprehensive services at a primary care facility"],"answer":3,"explanation":"Primary care provides accessible first-contact and continuing health services.","topic":"Community health","difficulty":"Moderate"},{"id":"MBBS-073","question":"A family adoption programme in medical education is intended to:","options":["Avoid community contact","Expose students to family and community health needs over time","Provide commercial insurance","Replace all clinical subjects"],"answer":1,"explanation":"Family and community exposure supports understanding of social determinants and continuity of care.","topic":"Community health","difficulty":"Easy"},{"id":"MBBS-074","question":"A scientific hypothesis should be:","options":["Testable and capable of being supported or refuted by evidence","Impossible to evaluate","Based only on personal preference","Guaranteed to be correct"],"answer":0,"explanation":"A scientific hypothesis is a testable proposed explanation.","topic":"Research literacy","difficulty":"Easy"},{"id":"MBBS-075","question":"The mean of a dataset is calculated by:","options":["Taking the most frequent observation","Subtracting the smallest from the largest","Choosing the middle value only","Adding all observations and dividing by their number"],"answer":3,"explanation":"The arithmetic mean is the sum divided by the number of observations.","topic":"Biostatistics","difficulty":"Moderate"},{"id":"MBBS-076","question":"The median is particularly useful when a dataset contains:","options":["Extreme outliers or a skewed distribution","No numerical values","Only identical observations","Exactly one observation only"],"answer":0,"explanation":"The median is less affected by extreme values than the mean.","topic":"Biostatistics","difficulty":"Easy"},{"id":"MBBS-077","question":"The most appropriate first step when a patient begins to deteriorate during a supervised learning encounter is to:","options":["Alert the supervising clinician and follow the emergency response pathway","Leave the patient alone","Continue the teaching session","Attempt an unfamiliar procedure"],"answer":0,"explanation":"Students should seek immediate help and act within competence and institutional emergency protocols.","topic":"Patient safety","difficulty":"Easy"},{"id":"MBBS-078","question":"Which term describes the ability of a test to identify people who truly have a condition?","options":["Prevalence","Specificity","Sensitivity","Incidence"],"answer":2,"explanation":"Sensitivity is the proportion of affected individuals who test positive.","topic":"Epidemiology","difficulty":"Moderate"},{"id":"MBBS-079","question":"Specificity of a diagnostic test is its ability to:","options":["Predict treatment duration","Correctly identify people who do not have the condition","Measure disease severity","Correctly identify all affected people"],"answer":1,"explanation":"Specificity is the proportion of unaffected individuals who test negative.","topic":"Epidemiology","difficulty":"Easy"},{"id":"MBBS-080","question":"Incidence refers to:","options":["All existing cases at one point only","The average age of patients","The number of hospital beds","The occurrence of new cases in a population over a specified period"],"answer":3,"explanation":"Incidence measures new events over time in a defined population.","topic":"Epidemiology","difficulty":"Easy"},{"id":"MBBS-081","question":"Prevalence refers to:","options":["The proportion or number of people with a condition in a population at a given time or period","The rate of recovery from surgery","The number of tests performed","Only new cases"],"answer":0,"explanation":"Prevalence includes existing cases in a population at a defined time or period.","topic":"Epidemiology","difficulty":"Moderate"},{"id":"MBBS-082","question":"Which study design is generally most useful for measuring prevalence at a point in time?","options":["Cross-sectional study","Randomised controlled trial only","Case report","Animal experiment"],"answer":0,"explanation":"Cross-sectional studies assess exposure and outcome at a defined point or short period.","topic":"Research methods","difficulty":"Easy"},{"id":"MBBS-083","question":"A randomised controlled trial uses random allocation primarily to:","options":["Guarantee no adverse effects","Ensure all participants receive the same outcome","Reduce selection bias and balance known and unknown factors on average","Remove the need for consent"],"answer":2,"explanation":"Randomisation helps create comparable groups and supports causal inference when properly conducted.","topic":"Research methods","difficulty":"Easy"},{"id":"MBBS-084","question":"The main purpose of a control group in a clinical study is to:","options":["Provide a comparison for interpreting the intervention's effects","Ensure all subjects receive the intervention","Replace outcome measurement","Guarantee statistical significance"],"answer":0,"explanation":"A control group helps estimate what would have happened without the intervention or under comparison care.","topic":"Research methods","difficulty":"Moderate"},{"id":"MBBS-085","question":"Which organelle modifies and packages many proteins for transport?","options":["Golgi apparatus","Centrosome","Peroxisome","Nucleus"],"answer":0,"explanation":"The Golgi apparatus processes, sorts and packages proteins and lipids.","topic":"Cell biology","difficulty":"Easy"},{"id":"MBBS-086","question":"The rough endoplasmic reticulum is studded with:","options":["Ribosomes","Lysosomes","Glycogen granules","Centrioles"],"answer":0,"explanation":"Ribosomes attached to rough ER synthesise proteins destined for secretion, membranes or organelles.","topic":"Cell biology","difficulty":"Easy"},{"id":"MBBS-087","question":"Mitosis produces daughter cells that generally have:","options":["Half the chromosome number","The same chromosome number as the parent cell","No chromosomes","Twice the chromosome number in every case"],"answer":1,"explanation":"Mitosis maintains chromosome number in somatic cell division.","topic":"Cell biology","difficulty":"Moderate"},{"id":"MBBS-088","question":"Meiosis is important because it:","options":["Doubles chromosome number in every gamete","Repairs all tissues directly","Produces identical skin cells","Produces haploid gametes and contributes to genetic variation"],"answer":3,"explanation":"Meiosis halves chromosome number and generates variation through recombination and independent assortment.","topic":"Cell biology","difficulty":"Easy"},{"id":"MBBS-089","question":"Which feature is characteristic of arteries compared with veins?","options":["Thinner walls than capillaries","Thicker walls with more smooth muscle and elastic tissue","Valves in every artery","Always carry deoxygenated blood"],"answer":1,"explanation":"Arteries withstand higher pressure and have thicker muscular and elastic walls.","topic":"Histology","difficulty":"Easy"},{"id":"MBBS-090","question":"The portal triad in a liver lobule includes a branch of the hepatic artery, portal vein and:","options":["Bile duct","Renal duct","Ureter","Pancreatic duct"],"answer":0,"explanation":"The portal triad contains a portal venule, hepatic arteriole and bile ductule.","topic":"Histology","difficulty":"Moderate"},{"id":"MBBS-091","question":"The basic filtration unit in the kidney is the:","options":["Sarcomere","Nephron","Alveolus","Hepatic lobule"],"answer":1,"explanation":"The nephron performs filtration and selective reabsorption and secretion.","topic":"Renal physiology","difficulty":"Easy"},{"id":"MBBS-092","question":"Which plasma electrolyte is most important for the resting membrane potential of many cells?","options":["Iron","Iodide","Fluoride","Potassium"],"answer":3,"explanation":"The high intracellular potassium concentration and membrane permeability to K+ strongly influence resting potential.","topic":"Physiology","difficulty":"Easy"},{"id":"MBBS-093","question":"The sinoatrial node is called the natural pacemaker because it:","options":["Produces red blood cells","Spontaneously generates impulses that normally initiate each heartbeat","Closes the aortic valve","Filters venous blood"],"answer":1,"explanation":"SA nodal cells have spontaneous depolarisation and usually set the heart's rhythm.","topic":"Cardiac physiology","difficulty":"Moderate"},{"id":"MBBS-094","question":"The Frank-Starling mechanism relates increased ventricular filling to:","options":["Immediate valve closure","Reduced stroke volume in every case","Increased force of contraction within physiological limits","No change in contraction"],"answer":2,"explanation":"Greater end-diastolic stretch can increase contraction force and stroke volume within normal limits.","topic":"Cardiac physiology","difficulty":"Easy"},{"id":"MBBS-095","question":"Which factor shifts the oxygen-haemoglobin dissociation curve to the right?","options":["Increased temperature","Reduced 2,3-BPG","Reduced carbon dioxide","Reduced hydrogen ion concentration"],"answer":0,"explanation":"Higher temperature, CO2, H+ and 2,3-BPG reduce haemoglobin oxygen affinity and shift the curve right.","topic":"Respiratory physiology","difficulty":"Easy"},{"id":"MBBS-096","question":"The main respiratory stimulus under normal resting conditions in many healthy adults is:","options":["Rise in body calcium","Rise in blood glucose","Rise in arterial carbon dioxide sensed through changes in CSF hydrogen ion concentration","Fall in plasma albumin"],"answer":2,"explanation":"Central chemoreceptors respond mainly to CSF H+ generated as CO2 diffuses across the blood-brain barrier.","topic":"Respiratory physiology","difficulty":"Moderate"},{"id":"MBBS-097","question":"Which renal process moves a substance from tubular fluid back into blood?","options":["Reabsorption","Filtration","Excretion","Secretion"],"answer":0,"explanation":"Reabsorption returns water and solutes from tubular fluid to the peritubular circulation.","topic":"Renal physiology","difficulty":"Easy"},{"id":"MBBS-098","question":"The countercurrent multiplier is associated mainly with the:","options":["Alveolar duct","Loop of Henle","Proximal stomach","Pancreatic acinus"],"answer":1,"explanation":"The loop of Henle helps establish the medullary osmotic gradient used to concentrate urine.","topic":"Renal physiology","difficulty":"Easy"},{"id":"MBBS-099","question":"Which enzyme catalyses conversion of carbon dioxide and water to carbonic acid in red cells?","options":["Amylase","Pepsin","Lactase","Carbonic anhydrase"],"answer":3,"explanation":"Carbonic anhydrase accelerates reversible formation of carbonic acid, supporting CO2 transport.","topic":"Biochemistry","difficulty":"Moderate"},{"id":"MBBS-100","question":"A competitive enzyme inhibitor typically:","options":["Binds only to DNA","Competes with substrate for the active site and can be overcome by increased substrate concentration","Destroys the enzyme permanently in every case","Always increases Vmax"],"answer":1,"explanation":"Competitive inhibition increases apparent Km while Vmax remains the same in the classic model.","topic":"Biochemistry","difficulty":"Easy"}]}});
